                    } "r_extract_condition";
                } "r_condition_answer_code_not_cancer";
            } "r_condition_answer_code";
        } "r_condition_answer";
    } "r_condition_item";
}

group ExtractOtherCancerType(source src: QuestionnaireResponse, source encounter: Encounter, source patient: Patient, target bundle: Bundle) {
    src.item as conditionItem where(linkId = "other-cancer-type" and answer.exists()) then {
            src -> bundle.entry as entry, entry.resource = create('Condition') as condition then {
                src -> condition.id = uuid() "r_condition_id";
                src -> condition.category = cc("https://smartregister.org/", "other-cancer-problem-list-item") "r_condition_category";
                src -> condition.code = create('CodeableConcept') as concept then {
                    src -> concept.coding = create("Coding") as coding then {
                        src -> coding.system = "http://snomed.info/sct" "r_condition_code_system";
                        src -> coding.code = "363346000" "r_condition_code_code";
                        src -> coding.display = "Cancer" "r_condition_code_display";
                    } "r_condition_code";
                    src -> concept.text = "Cancer" "r_condition_code_text";   
                } "r_condition_code";
                src -> condition.subject = patient "r_condition_subject";
                src -> condition.encounter = reference(encounter) "r_condition_encounter";
                src -> condition.recordedDate = evaluate(src, now()) "r_condition_recordedDate";
                src -> condition.recorder = evaluate(src, $this.generalPractitioner.first()) "r_condition_recorder";
                src -> condition.note = create('Annotation') as note then {
                    src -> note.text = evaluate(conditionItem, $this.answer.value) "r_condition_note_text";
                } "r_condition_note";
            } "r_extract_condition";
