}

group ExtractSurgicalProcedures(source src: QuestionnaireResponse, source encounter: Encounter, source patient: Patient, target bundle: Bundle) {
    src.item as procedureItem where(linkId = "surgical-procedures" and answer.exists()) then {
            src -> bundle.entry as entry, entry.resource = create('Procedure') as procedure then {
                src -> procedure.id = uuid() "r_procedure_id";
                src -> procedure.status = "completed" "r_procedure_status";
                src -> procedure.category = create('CodeableConcept') as category then {
                    src -> category.coding = create("Coding") as coding then {
                        src -> coding.system = "http://snomed.info/sct" "r_procedure_category_system";
                        src -> coding.code = "387713003" "r_procedure_category_code";
                        src -> coding.display = "Diagnostic procedure (procedure)" "r_procedure_category_display";
                    } "r_procedure_category";
                    src -> category.text = "Diagnostic procedure" "r_procedure_category_text";
                } "r_procedure_category";
                src -> procedure.subject = patient "r_procedure_subject";
                src -> procedure.encounter = reference(encounter) "r_procedure_encounter";
                src -> procedure.performer = evaluate(src, $this.generalPractitioner.first()) "r_procedure_performer";
                src -> procedure.note = create('Annotation') as note then {
                    src -> note.text = evaluate(procedureItem, $this.answer.value) "r_procedure_note_text";
                } "r_procedure_note";
            } "r_extract_procedure";
    } "r_procedure_item";
}

group ExtractIllnessesWithinTheLastYear(source src: QuestionnaireResponse, source encounter: Encounter, source patient: Patient, target bundle: Bundle) {
    src.item as illnessItem where(linkId = "illnesses-within-the-last-year" and answer.exists()) then {
        illnessItem.answer as answer then { 
            src->evaluate(answer, $this.value.code) as answerCode then {
                src where(answerCode != "R69") then {
                    src -> bundle.entry as entry, entry.resource = create('Condition') as condition then {
                        src -> condition.id = uuid() "r_condition_id";
                         src -> condition.clinicalStatus = cc("http://terminology.hl7.org/CodeSystem/condition-clinical", "active") "r_condition_clinical_status";
                        src -> condition.verificationStatus = cc("http://terminology.hl7.org/CodeSystem/condition-ver-status", "confirmed") "r_condition_verification_status";
                        src -> condition.category = cc("https://smartregister.org/", "illness-problem-list-item") "r_condition_category";
                        src -> condition.code = create('CodeableConcept') as concept then {
                            src -> concept.coding = create("Coding") as coding then {
                                src -> coding.system = evaluate(answer, answer.value.system) "r_condition_code_system";
                                src -> coding.code = evaluate(answer, answer.value.code) "r_condition_code_code";
                                src -> coding.display = evaluate(answer, answer.value.display) "r_condition_code_display";
                            } "r_condition_code";
                            src -> concept.text = evaluate(answer, answer.value.display) "r_condition_code_text";
                        } "r_condition_code";
                        src -> condition.subject = patient "r_condition_subject";
                        src -> condition.encounter = reference(encounter) "r_condition_encounter";
                        src -> condition.recordedDate = evaluate(src, now()) "r_condition_recordedDate";
                        src -> condition.recorder = evaluate(src, $this.generalPractitioner.first()) "r_condition_recorder";
                    } "r_extract_condition";
                } "r_condition_answer_code_not_illness";
            } "r_condition_answer_code";
        } "r_condition_answer"; 
    } "r_condition_item";
}

