group ExtractReasonForReferral(source src: QuestionnaireResponse, source encounter: Encounter, source patient: Patient, target bundle: Bundle) {
    src.item as wasReferredItem where(linkId = "case-was-referred") then {
        wasReferredItem.answer as wasReferredAnswer then {
            wasReferredAnswer.item as reasonForReferralItem where(linkId = "reason-for-referral" and answer.exists()) then {
            src -> bundle.entry as entry, entry.resource = create('Observation') as observation then {
                src -> observation.id = uuid() "r_observation_id";
                src -> observation.status = "final" "r_observation_status";
                src -> observation.category = cc("http://terminology.hl7.org/CodeSystem/observation-category", "social-history") "r_observation_category";
                src -> observation.code = create('CodeableConcept') as concept then {
                    src -> concept.coding = create("Coding") as coding then {
                        src -> coding.system = "http://snomed.info/sct" "r_observation_code_system";
                        src -> coding.code = "440378000" "r_observation_code_code";
                        src -> coding.display = "Referral for" "r_observation_code_display"; 
                    } "r_observation_code";
                    src -> concept.text = "Referral for" "r_observation_code_text";
                } "r_observation_code";
                src -> observation.subject = patient "r_observation_subject";
                src -> observation.encounter = reference(encounter) "r_observation_encounter";
                src -> observation.effective = evaluate(src, now()) "r_observation_effective";
                src -> observation.performer = evaluate(src, $this.generalPractitioner.first()) "r_observation_performer";
                src->evaluate(reasonForReferralItem, $this.answer.value.code) as reasonForReferralCode then {
                    src where(reasonForReferralCode != "other") then {
                        src -> observation.value = create("CodeableConcept") as concept then {
                            src -> concept.coding = create("Coding") as coding then {
                                src -> coding.system = evaluate(reasonForReferralItem, $this.answer.value.system) "r_observation_code_system";
                                src -> coding.code = evaluate(reasonForReferralItem, $this.answer.value.code) "r_observation_code_code";
                                src -> coding.display = evaluate(reasonForReferralItem, $this.answer.value.display) "r_observation_code_display";
                            } "r_observation_code";
                        } "r_extract_observation_value_code";
                    } "r_where_reason_code_is_not_other";
                    src where(reasonForReferralCode = "other") then {
                        src.item as otherReasonForReferralItem where(linkId = "other-referral-reason" and answer.exists()) then {
                            src -> observation.value = evaluate(otherReasonForReferralItem, $this.answer.value) "r_obs_value_string";
                        } "r_extract_other_observation_value_text";
                    } "r_where_reason_code_is_other";
                } "r_evaluate_reason_code";
            } "r_extract_observation";
            } "r_observation_item";
        } "r_reason_for_referral_item";
    } "r_was_referred_item";
}

